const fs = require('fs');
const s = fs.readFileSync(0, 'utf8').trim();

const suits = { C: 0, E: 1, U: 2, P: 3 };
const counts = Array.from({ length: 4 }, () => Array(14).fill(0));

for (let i = 0; i < s.length; i += 3) {
  const rank = parseInt(s.slice(i, i + 2), 10);
  const suit = suits[s[i + 2]];
  counts[suit][rank]++;
}

const order = ['C', 'E', 'U', 'P'];
const output = [];

for (const suit of order) {
  const arr = counts[suits[suit]];
  let duplicate = false;
  let missing = 0;

  for (let r = 1; r <= 13; r++) {
    if (arr[r] > 1) duplicate = true;
    if (arr[r] === 0) missing++;
  }

  output.push(duplicate ? 'erro' : missing);
}

process.stdout.write(output.join('\n'));
